var css_248z = "/* ModernPieChart widget styles */\n\n.mpc-container {\n    display: flex;\n    flex-direction: column;\n    align-items: stretch;\n    padding: 20px;\n    background: #ffffff;\n    border-radius: 20px;\n    box-shadow: 0 10px 30px rgba(15, 23, 42, .08);\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n    width: 100%;\n    height: 100%;\n    box-sizing: border-box;\n    transition: all .25s ease;\n}\n\n.mpc-container:hover {\n    transform: translateY(-2px);\n    box-shadow: 0 18px 45px rgba(15, 23, 42, .14);\n}\n\n.mpc-title {\n    margin: 0 0 16px 0;\n    font-size: 18px;\n    font-weight: 600;\n    color: #1f2937;\n    text-align: center;\n}\n\n.mpc-loading,\n.mpc-empty {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    height: 200px;\n    color: #9ca3af;\n    font-size: 14px;\n}\n\n/* Chart canvas wrapper */\n\n.mpc-chart-canvas-wrap {\n    position: relative;\n    width: 100%;\n    /* height is intentionally not set here — it's controlled by the inline\n       flex: 1 1 0% style, which makes this element fill whatever vertical\n       space is left in the (now fixed-height) .mpc-container after the\n       header and legend. */\n    background: transparent;\n    filter: drop-shadow(0 6px 14px rgba(15, 23, 42, 0.12));\n    overflow: visible;\n}\n\n.mpc-container.mpc-dark .mpc-chart-canvas-wrap {\n    filter: drop-shadow(0 6px 18px rgba(0, 0, 0, 0.5));\n}\n\n/* Inline labels fallback (when legend is hidden but showLabels is true) */\n\n.mpc-inline-labels {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 10px 18px;\n    justify-content: center;\n    margin-top: 12px;\n    padding: 0 8px;\n}\n\n.mpc-inline-label {\n    display: flex;\n    align-items: center;\n    font-size: 12px;\n    font-weight: 500;\n    position: relative;\n    padding-left: 16px;\n}\n\n.mpc-inline-label::before {\n    content: \"\";\n    position: absolute;\n    left: 0;\n    top: 50%;\n    transform: translateY(-50%);\n    width: 10px;\n    height: 10px;\n    border-radius: 50%;\n    background: currentColor;\n}\n\n/* Export button — pill shape, gradient, icon chip, shimmer sweep on hover */\n\n.mpc-export-btn {\n    position: relative;\n    padding: 6px 16px 6px 6px;\n    border: none;\n    border-radius: 999px;\n    /* background is intentionally not set here — it's applied inline from\n       buttonTheme.background (derived from chartTheme/startColor/endColor\n       and dark mode), so the button always tracks the chart's theme. */\n    color: #ffffff;\n    font-size: 12px;\n    font-weight: 600;\n    cursor: pointer;\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    overflow: hidden;\n    flex-shrink: 0;\n    transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s ease;\n    /* box-shadow color is intentionally not set here — see boxShadow inline\n       style, which tracks the same theme color as the background. */\n}\n\n.mpc-export-btn::after {\n    content: \"\";\n    position: absolute;\n    top: 0;\n    left: -60%;\n    width: 40%;\n    height: 100%;\n    background: linear-gradient(120deg, transparent, rgba(255, 255, 255, 0.35), transparent);\n    transform: skewX(-20deg);\n    transition: left 0.5s ease;\n}\n\n.mpc-export-btn:hover:not(:disabled)::after {\n    left: 130%;\n}\n\n.mpc-export-btn:hover:not(:disabled) {\n    transform: translateY(-1px);\n}\n\n.mpc-export-btn:active:not(:disabled) {\n    transform: translateY(0);\n}\n\n.mpc-export-btn:disabled {\n    opacity: 0.6;\n    cursor: not-allowed;\n}\n\n.mpc-btn-icon-chip {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    width: 20px;\n    height: 20px;\n    border-radius: 50%;\n    background: rgba(255, 255, 255, 0.18);\n    flex-shrink: 0;\n}\n\n.mpc-btn-spinner {\n    width: 12px;\n    height: 12px;\n    border: 2px solid rgba(255, 255, 255, 0.4);\n    border-top-color: #ffffff;\n    border-radius: 50%;\n    animation: mpc-spin 0.7s linear infinite;\n}\n\n@keyframes mpc-spin {\n    to {\n        transform: rotate(360deg);\n    }\n}\n\n/* Dark theme support */\n\n.mpc-container.mpc-dark {\n    background: #18181b;\n}\n\n.mpc-container.mpc-dark .mpc-title {\n    color: #f4f4f5;\n}\n\n.mpc-container.mpc-dark .mpc-loading,\n.mpc-container.mpc-dark .mpc-empty {\n    color: #6b7280;\n}\n\n.mpc-container.mpc-dark .mpc-inline-label {\n    color: #e5e7eb;\n}\n\n/* Modern HTML tooltip: left accent bar, uppercase label, bold value, % highlight */\n\n.mpc-tooltip {\n    position: absolute;\n    top: 0;\n    left: 0;\n    pointer-events: none;\n    opacity: 0;\n    transform: translate(-50%, -100%) scale(0.92);\n    transition: opacity 0.15s ease, transform 0.15s cubic-bezier(0.34, 1.56, 0.64, 1);\n    display: flex;\n    align-items: stretch;\n    border-radius: 10px;\n    background: rgba(20, 20, 24, 0.88);\n    backdrop-filter: blur(14px);\n    -webkit-backdrop-filter: blur(14px);\n    box-shadow:\n        0 12px 32px rgba(0, 0, 0, 0.5),\n        0 2px 8px rgba(0, 0, 0, 0.3),\n        inset 0 1px 0 rgba(255, 255, 255, 0.06);\n    white-space: nowrap;\n    z-index: 10;\n    overflow: hidden;\n}\n\n.mpc-tooltip-swatch {\n    width: 4px;\n    flex-shrink: 0;\n}\n\n.mpc-tooltip-text {\n    display: flex;\n    flex-direction: column;\n    gap: 3px;\n    padding: 10px 14px;\n}\n\n.mpc-tooltip-label {\n    font-size: 10px;\n    font-weight: 600;\n    letter-spacing: 0.04em;\n    text-transform: uppercase;\n    color: #9ca3af;\n}\n\n.mpc-tooltip-value {\n    font-size: 15px;\n    font-weight: 700;\n    color: #ffffff;\n    line-height: 1.2;\n}\n\n.mpc-tooltip-pct {\n    color: #6ee7b7;\n    font-weight: 600;\n    font-size: 12px;\n}\n\n/* Leader line + dot connecting the tooltip to the hovered slice */\n\n.mpc-tooltip-line-svg {\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    pointer-events: none;\n    overflow: visible;\n    z-index: 20;\n}\n\n.mpc-tooltip-line {\n    stroke-width: 2;\n    opacity: 0;\n    transition: opacity 0.12s ease;\n    stroke-linecap: round;\n    filter: drop-shadow(0 0 2px rgba(255, 255, 255, 0.8));\n}\n\n.mpc-tooltip-dot {\n    opacity: 0;\n    transition: opacity 0.12s ease;\n    stroke: #ffffff;\n    stroke-width: 2;\n    filter: drop-shadow(0 0 4px rgba(0, 0, 0, 0.7));\n}\n\n.mpc-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 16px;\n    margin-bottom: 16px;\n    flex-shrink: 0;\n}\n\n.mpc-header .mpc-title {\n    margin: 0;\n    text-align: left;\n}\n\n/* Permanent per-slice leader-line labels (elbow line + external text,\n   value shown directly on larger arcs) */\n\n.mpc-external-labels-svg {\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    pointer-events: none;\n    overflow: visible;\n    z-index: 8;\n}\n\n.mpc-external-label-line {\n    fill: none;\n    stroke-width: 1.75;\n    opacity: 1;\n    filter: drop-shadow(0 0 1.5px rgba(255, 255, 255, 0.9));\n}\n\n.mpc-container.mpc-dark .mpc-external-label-line {\n    filter: drop-shadow(0 0 1.5px rgba(0, 0, 0, 0.6));\n}\n\n.mpc-external-label-dot {\n    opacity: 1;\n}\n\n.mpc-external-label-text {\n    font-size: 12px;\n    font-weight: 600;\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n}\n\n.mpc-external-label-text-light {\n    fill: #374151;\n}\n\n.mpc-external-label-text-dark {\n    fill: #e5e7eb;\n}\n\n.mpc-external-arc-value {\n    font-size: 13px;\n    font-weight: 700;\n    fill: #1f2937;\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n    paint-order: stroke;\n    stroke: rgba(255, 255, 255, 0.55);\n    stroke-width: 3px;\n    stroke-linejoin: round;\n}\n\n.mpc-external-label-value {\n    font-weight: 500;\n    opacity: 0.7;\n}\n\n/* Overlay */\n\n.mpc-modal-overlay {\n    position: fixed;\n    inset: 0;\n    background: rgba(0, 0, 0, .45);\n    backdrop-filter: blur(4px);\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    z-index: 9999;\n}\n\n/* Modal */\n\n.mpc-modal {\n    width: 90%;\n    max-width: 1200px;\n    height: 85vh;\n    overflow: hidden;\n    display: flex;\n    flex-direction: column;\n    background: #ffffff;\n}\n\n/* Header */\n\n.mpc-modal-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 16px 20px;\n    border-bottom: 1px solid #ddd;\n}\n\n.mpc-close-button {\n    border: none;\n    background: transparent;\n    cursor: pointer;\n    font-size: 22px;\n}\n\n/* Info */\n\n.mpc-modal-info {\n    padding: 12px 20px;\n    font-weight: 600;\n}\n\n/* Table */\n\n.mpc-modal-table-container {\n    flex: 1;\n    overflow: auto;\n    min-height: 0;\n    width: 100%;\n    background: #ffffff;\n}\n\n.mpc-modal-table {\n    width: 100%;\n    border-collapse: collapse;\n    table-layout: fixed;\n}\n\n.mpc-modal-table th {\n    position: sticky;\n    top: 0;\n    background: #f5f5f5;\n    z-index: 1;\n}\n\n.mpc-modal-table th,\n.mpc-modal-table td {\n    padding: 12px 14px;\n    border: 1px solid #e5e5e5;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n    vertical-align: middle;\n}\n\n.mpc-modal-table thead th {\n    position: sticky;\n    top: 0;\n    background: #ffffff;\n    z-index: 5;\n    border-bottom: 2px solid #d9d9d9;\n}\n\n.mx-theme-dark .mpc-modal-table thead th,\n[data-mx-color-scheme=\"dark\"] .mpc-modal-table thead th {\n    background: #252526;\n    color: #fff;\n}\n\n.mpc-modal-table th:first-child,\n.mpc-modal-table td:first-child {\n    position: sticky;\n    left: 0;\n    background: inherit;\n    z-index: 3;\n}\n\n.mpc-modal-table thead th:first-child {\n    z-index: 6;\n}\n\n.mpc-search-input {\n    width: 320px;\n    max-width: 100%;\n    padding: 10px 14px;\n    font-size: 14px;\n}\n\n.mpc-search-container {\n    padding: 12px 24px 16px;\n}\n\n.mpc-modal-table tbody tr:nth-child(even) {\n    background: #fafafa;\n}\n\n.mpc-modal-table tbody tr:hover {\n    background: #eaf3ff;\n}\n\n.mpc-col-materialno {\n    width: 180px;\n}\n\n.mpc-col-message {\n    width: 520px;\n    white-space: normal;\n    word-break: break-word;\n}\n\n.mpc-col-status {\n    width: 90px;\n    text-align: center;\n}\n\n.mpc-col-createddate,\n.mpc-col-changeddate {\n    width: 180px;\n}\n\n.mpc-col-materialid,\n.mpc-col-sapmaterialid {\n    width: 180px;\n}\n\n.mpc-modal-toolbar {\n    display: flex;\n    justify-content: flex-end;\n    padding: 10px 24px;\n}\n\n.mpc-modal-export-btn {\n    background: #107c41;\n    color: white;\n    border: none;\n    border-radius: 6px;\n    padding: 10px 18px;\n    cursor: pointer;\n    font-size: 14px;\n    font-weight: 600;\n}\n\n.mpc-modal-export-btn:hover {\n    background: #0e6b38;\n}\n\n/* Dark mode — the modal is rendered via a portal straight to <body>, so it\n   sits outside .mpc-container in the DOM and can't be reached by\n   \".mpc-container.mpc-dark ...\" ancestor selectors. isDark is passed down\n   as a prop instead and toggles .mpc-modal-dark directly on the overlay. */\n\n.mpc-modal-overlay.mpc-modal-dark {\n    background: rgba(0, 0, 0, .6);\n}\n\n.mpc-modal-dark .mpc-modal {\n    background: #18181b;\n    color: #f4f4f5;\n}\n\n.mpc-modal-dark .mpc-modal-header {\n    border-bottom: 1px solid #3f3f46;\n}\n\n.mpc-modal-dark .mpc-modal-header h3 {\n    color: #f4f4f5;\n}\n\n.mpc-modal-dark .mpc-close-button {\n    color: #d4d4d8;\n}\n\n.mpc-modal-dark .mpc-close-button:hover {\n    color: #f4f4f5;\n}\n\n.mpc-modal-dark .mpc-modal-info {\n    color: #d4d4d8;\n}\n\n.mpc-modal-dark .mpc-modal-table-container {\n    background: #18181b;\n}\n\n.mpc-modal-dark .mpc-modal-table th,\n.mpc-modal-dark .mpc-modal-table td {\n    border-color: #3f3f46;\n}\n\n.mpc-modal-dark .mpc-modal-table thead th {\n    background: #27272a;\n    color: #f4f4f5;\n    border-bottom: 2px solid #52525b;\n}\n\n.mpc-modal-dark .mpc-modal-table tbody tr {\n    color: #e4e4e7;\n}\n\n.mpc-modal-dark .mpc-modal-table tbody tr:nth-child(even) {\n    background: #202023;\n}\n\n.mpc-modal-dark .mpc-modal-table tbody tr:hover {\n    background: #2c2c31;\n}\n\n.mpc-modal-dark .mpc-search-input {\n    background: #27272a;\n    border: 1px solid #3f3f46;\n    color: #f4f4f5;\n}\n\n.mpc-modal-dark .mpc-search-input::placeholder {\n    color: #a1a1aa;\n}\n\n.mpc-chart-outer {\n    display: flex;\n    flex-direction: column;\n    width: 100%;\n    flex: 1 1 0%;\n    min-height: 0;\n    overflow: visible;\n    /* Guarantees real space between the donut's leader-line labels and the\n       legend rendered right after it in the flex column — without this the\n       two sit flush against each other and any label near the bottom edge\n       visually runs into the legend row. */\n    gap: 10px;\n}\n\n.mpc-chart-outer-row {\n    flex-direction: row;\n    align-items: stretch;\n    min-height: 0;\n}\n\n/* Below ~480px wide, stack a left/right legend under the chart instead of\n   squeezing the donut sideways — a vertical legend column eats too much\n   width on narrow/mobile containers. */\n\n.mpc-chart-outer-row.mpc-compact {\n    flex-direction: column;\n}\n\n.mpc-chart-canvas-wrap {\n    /* Keeps the donut usable instead of collapsing to near-nothing when a\n       host page gives the widget a very short heightPx. */\n    min-height: 140px;\n}\n\n.mpc-compact .mpc-legend {\n    gap: 6px 10px;\n    padding: 8px 4px;\n}\n\n.mpc-compact .mpc-legend-horizontal {\n    grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));\n}\n\n.mpc-compact .mpc-legend-label {\n    font-size: 11px;\n}\n\n.mpc-compact .mpc-legend-dot {\n    width: 8px;\n    height: 8px;\n}\n\n.mpc-compact .mpc-header {\n    flex-wrap: wrap;\n    gap: 8px;\n}\n\n.mpc-compact .mpc-title {\n    font-size: 15px;\n}\n\n.mpc-legend {\n    display: grid;\n    gap: 8px 16px;\n    padding: 12px 4px;\n    flex-shrink: 0;\n}\n\n.mpc-legend-horizontal {\n    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));\n}\n\n.mpc-legend-vertical {\n    max-height: 100%;\n    overflow-y: auto;\n    align-self: stretch;\n    /* thin, unobtrusive scrollbar instead of the default chunky one */\n    scrollbar-width: thin;\n}\n\n.mpc-legend-vertical::-webkit-scrollbar {\n    width: 6px;\n}\n\n.mpc-legend-vertical::-webkit-scrollbar-thumb {\n    background: rgba(124, 58, 237, 0.25);\n    border-radius: 999px;\n}\n\n.mpc-legend-vertical::-webkit-scrollbar-track {\n    background: transparent;\n}\n\n.mpc-legend-item {\n    min-width: 0;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    background: none;\n    border: none;\n    padding: 4px 6px;\n    border-radius: 6px;\n    cursor: pointer;\n    text-align: left;\n    transition: background 0.12s ease;\n}\n\n.mpc-legend-item:hover {\n    background: rgba(124, 58, 237, 0.08);\n}\n\n.mpc-legend-dot {\n    width: 10px;\n    height: 10px;\n    border-radius: 50%;\n    flex-shrink: 0;\n}\n\n.mpc-legend-label {\n    font-size: 12px;\n    font-weight: 600;\n    color: #374151;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n}\n\n.mpc-legend-dark .mpc-legend-label {\n    color: #e5e7eb;\n}\n\n.mpc-legend-dark .mpc-legend-item:hover {\n    background: rgba(139, 92, 246, 0.15);\n}\n/*# sourceMappingURL=data:application/json;base64, */";
